import"./NZTpNUN0.js";import"./BkvxQF8z.js";import{t,P as n,q as o}from"./D3cAVrQp.js";const a={title:"The Synoptic Protocol",subtitle:"Epistemic Freedom, Information-System Accountability, Public-Interest Media, and Crisis Resilience",version:4.2,status:"Constitutional alignment revision and pilot-design basis",tier:"2 — Foundational Application and Information-System Interface",revision_date:"2026-08-01T00:00:00.000Z",supersedes:"The Synoptic Protocol v4.1"},{title:d,subtitle:u,version:p,status:h,tier:m,revision_date:y,supersedes:g}=a;var r=t("<h1>The Synoptic Protocol v4.2</h1> <h2>Epistemic Freedom, Information-System Accountability, Public-Interest Media, and Crisis Resilience</h2> <h3>Related frameworks</h3> <ul><li><strong>Justice Systems Framework</strong> — due process, adjudication, remedy, and enforcement interfaces</li> <li><strong>Aurora Accord</strong> — data rights, privacy, identity, and audience-research boundaries</li> <li><strong>Technology Governance Framework</strong> — platform systems, AI interfaces, and technical standards</li> <li><strong>Integrated Meta-Governance Framework</strong> — cross-domain coordination and institutional dispute resolution</li> <li><strong>AUBI Framework</strong> — material security and epistemic rights</li> <li><strong>Genesis Protocol</strong> — pre-constitutional preparation, pilots, first seating, and authority provenance</li> <li><strong>Treaty for Our Only Home</strong> — Treaty jurisdiction, institutions, enforcement, and emergency authority</li> <li><strong>Constitutional Interface Specification</strong> — plural legitimacy, decision classes, observation, and framework authority boundaries</li> <li><strong>Indigenous Sovereignty and Planetary Healing</strong> — Indigenous knowledge authority, consent, and protected non-transfer</li></ul> <h3>Version history</h3> <ul><li><strong>Editorial edition (2026-08-02).</strong> No substantive change. Added this version history and a related-frameworks section, neither of which the document previously had; the v4.2 entry below is reconstructed from the Protocol’s own executive summary and earlier entries remain to be recorded. Removed version pins from body prose so that a reference names an instrument rather than asserting a live dependency that goes stale when another framework moves; editions consulted are recorded here instead. Editions consulted: Justice Systems Framework v1.4; Aurora Accord v1.3; Technology Governance Framework v3.6; Integrated Meta-Governance v1.5; AUBI v2.5; Genesis Protocol v0.9; Treaty for Our Only Home v1.3; Constitutional Interface Specification v0.1; Indigenous Sovereignty and Planetary Healing v1.1.</li> <li><strong>4.2 (2026-08-01):</strong> Constitutional alignment revision of The Synoptic Protocol v4.1. Preserved v4.1’s strongest commitments — media literacy, public-interest journalism, algorithmic choice, correction, dissent records, local dialogue, source protection, archive resilience, crisis communication, and accountability — while separating three objects v4.1 often combined: claims and interpretations, information-system conduct, and legally cognizable harms. Established that a media finding, scientific consensus, community testimony, Indigenous knowledge claim, audit, or public dashboard may be important evidence without becoming law. Separated eight functions across journalism, literacy, deliberation, research, platform regulation, crisis coordination, source and archive protection, and adjudication. Required that the phrase “circuit breaker” be replaced by a named authority class, and barred self-activation and self-renewal of interim restrictions.</li> <li><strong>Earlier editions:</strong> not yet recorded in this document.</li></ul> <hr> <blockquote><p><strong>Governing principle:</strong> The Synoptic Protocol protects the freedom and institutional conditions to seek, test, communicate, contest, and revise claims. It does not decide reality on behalf of the public.</p></blockquote> <hr> <h1>Executive summary</h1> <p>Shared public understanding is shaped by more than the truth or falsity of isolated statements. It is shaped by media ownership, advertising incentives, recommender systems, targeting, language access, archives, education, source protection, institutional credibility, state power, platform concentration, and the material conditions under which people can inquire and speak.</p> <p>This framework governs those <strong>conditions and systems</strong> without creating an official narrator of reality. It preserves the strongest commitments of Synoptic v4.1: media literacy, public-interest journalism, algorithmic choice, correction, dissent records, local dialogue, source protection, archive resilience, crisis communication, and accountability for amplification systems. It retires the combined global epistemic council, institution-triggered truth flags, developmental audience classification, mandatory therapeutic reframing, self-activating epistemic emergencies, covert resilience cells, and any presumption that public funding confers authority to determine truth.</p> <p>The framework distinguishes three objects that v4.1 often combined:</p> <ol><li><strong>claims and interpretations</strong>, which may be investigated, supported, challenged, corrected, or remain unresolved;</li> <li><strong>information-system conduct</strong>, including targeting, sponsorship, automation, ranking, recommendation, monetization, virality, impersonation, and suppression;</li> <li><strong>legally cognizable harms</strong>, which require a valid source of law, evidence, jurisdiction, due process, and remedy.</li></ol> <p>A media institution’s finding, a scientific consensus, a community testimony, an Indigenous knowledge claim, an audit, or a public dashboard may be important evidence. None becomes law merely because this framework recognizes it.</p> <p>The Protocol separates eight functions:</p> <ul><li>public-interest journalism and media;</li> <li>media literacy and public education;</li> <li>public deliberation and dialogue;</li> <li>information-system research;</li> <li>platform standards, assessment, and lawful regulation;</li> <li>crisis public-information coordination;</li> <li>journalism, source, archive, and community protection;</li> <li>adjudication and remedy through Justice Systems and other competent legal orders.</li></ul> <p>Its platform principle is:</p> <blockquote><p><strong>Amplification systems may carry duties because they shape reach, targeting, incentives, dependencies, and foreseeable harm. Those duties must be defined through valid law and cannot be activated merely by an official truth label.</strong></p></blockquote> <p>Its public-media principle is:</p> <blockquote><p><strong>Public funding can protect journalism from commercial extraction only when it also protects journalism from governments, funders, epistemic councils, Treaty institutions, platforms, and the GGF itself.</strong></p></blockquote> <p>Its crisis principle is:</p> <blockquote><p><strong>Crisis information institutions authenticate, explain, translate, correct, and preserve communication. They do not manufacture counter-narratives or acquire authority to suppress dissent because uncertainty is dangerous.</strong></p></blockquote> <hr> <h1>1. Purpose, scope, status, and non-authority</h1> <h2>1.1 Purpose</h2> <p>The Synoptic Protocol provides constitutional and operational interfaces for:</p> <ul><li>protecting epistemic freedom and plural inquiry;</li> <li>supporting independent public-interest media;</li> <li>improving media literacy and public deliberation;</li> <li>making recommender, advertising, and amplification systems accountable;</li> <li>protecting users from covert targeting, deceptive automation, and synthetic impersonation;</li> <li>preserving journalism, sources, research, archives, and threatened knowledge;</li> <li>coordinating accurate and accessible public information during crises;</li> <li>connecting information-system harms to lawful investigation, adjudication, remedy, and appeal.</li></ul> <h2>1.2 Status</h2> <p>This document is a governance framework and pilot-design basis. It is not, by itself, a statute, tax instrument, court order, media licence, emergency declaration, content-removal mandate, accreditation requirement, or source of platform liability.</p> <h2>1.3 Non-authority clause</h2> <p>The Protocol does not itself:</p> <ul><li>determine truth, history, science, meaning, morality, conscience, or cultural authenticity;</li> <li>establish an official account of reality;</li> <li>create offences, civil liability, sanctions, taxes, tribunal jurisdiction, emergency powers, or compulsory media duties;</li> <li>authorize content removal, ranking suppression, account suspension, market exclusion, compelled correction, or forced algorithmic change;</li> <li>certify one feed, media institution, scientific body, or information source as the authoritative reality channel;</li> <li>represent Indigenous peoples, validate Indigenous knowledge, or require disclosure of protected knowledge;</li> <li>assign people or populations to developmental, psychological, intelligence, sanity, or worldview categories;</li> <li>authorize covert influence operations, hidden GGF affiliation, deniable cells, counter-propaganda, or political narrative management;</li> <li>create ownership of all data generated within a territory, BAZ, institution, or community;</li> <li>convert public trust, social harmony, reduced dissent, or belief change into a legal objective.</li></ul> <h2>1.4 No framework-to-law conversion</h2> <p>A Synoptic principle, classification, media finding, audit, standard, curriculum, state estimate, risk assessment, or recommendation becomes binding only when a competent authority adopts it through valid law, contract, procurement rule, charter, court order, Indigenous authority, or another independently valid instrument.</p> <h2>1.5 Scope boundary</h2> <p>The Protocol governs information-system conditions and institutional safeguards. It does not replace:</p> <ul><li>Justice Systems for jurisdiction, evidence, due process, interim orders, appeals, remedies, and enforcement;</li> <li>Aurora Accord for data, identity, privacy, profiling, records, deletion, protected non-transfer, and cross-border data flows;</li> <li>Technology Governance for technology-use assessment, standards, intervention provenance, and lifecycle impacts;</li> <li>Indigenous Sovereignty for Indigenous authority, consent, refusal, knowledge, and jurisdiction;</li> <li>Treaty for binding authority, rights, emergency powers, taxation, sanctions, and entry into force;</li> <li>Meta-Governance for bounded coordination among competent institutions;</li> <li>Genesis Protocol for pilots, negotiation, lawful adoption, first seating, and founder separation.</li></ul> <hr> <h1>2. Epistemic rights and freedoms</h1> <p>The Protocol protects a concrete bundle of rights rather than an enforceable right to one shared reality.</p> <h2>2.1 Freedom of inquiry</h2> <p>People and institutions may ask questions, investigate claims, test hypotheses, challenge consensus, revisit history, and publish uncertainty, subject to lawful protections for privacy, confidentiality, safety, and protected knowledge.</p> <h2>2.2 Freedom of expression and reception</h2> <p>People may communicate, receive, decline, criticize, interpret, translate, archive, and respond to information. These freedoms do not eliminate lawful responsibility for independently prohibited conduct or demonstrable harm.</p> <h2>2.3 Access to public information</h2> <p>Public authorities must provide timely, accessible, accurate records under applicable transparency law, with lawful exceptions for privacy, security, source protection, protected knowledge, and ongoing proceedings.</p> <h2>2.4 Freedom from covert manipulation</h2> <p>People have a protected interest in knowing when communication is paid, automated, synthetically generated, behaviourally targeted, or issued by a public authority. Covert psychographic targeting and deceptive impersonation may be restricted under valid law.</p> <h2>2.5 Recommendation and attention agency</h2> <p>Users should have meaningful control over personalization, ranking, notifications, advertising categories, profiling, feed modes, and recommendation history where technically feasible and legally required.</p> <h2>2.6 Correction, response, and contest</h2> <p>People materially affected by false or misleading factual assertions should have accessible routes to request correction, reply, annotation, review, or remedy. A request does not predetermine the result.</p> <h2>2.7 Source, journalist, researcher, and whistleblower protection</h2> <p>Confidential sources, lawful newsgathering, public-interest research, whistleblowing, and archive work require protection against retaliation, exposure, surveillance, and funding interference.</p> <h2>2.8 Accessibility and linguistic justice</h2> <p>Public-interest information and essential crisis communication must support disability access, minority languages, low-bandwidth use, offline access, plain-language explanation, and culturally appropriate translation.</p> <h2>2.9 Right to unresolved status</h2> <p>No person or institution is required to claim certainty where evidence, law, attribution, or meaning remains genuinely unresolved.</p> <hr> <h1>3. Authority provenance and functional separation</h1> <h2>3.1 Epistemic Action Authority Record</h2> <p>Before any consequential action, the acting body must record:</p> <ul><li>the actor and constituting instrument;</li> <li>the legal, contractual, editorial, technical, or voluntary source of authority;</li> <li>the action proposed;</li> <li>the persons, systems, claims, and jurisdictions affected;</li> <li>the evidence and uncertainty;</li> <li>the rights implicated;</li> <li>the duration and expiry condition;</li> <li>review, appeal, correction, and restoration routes;</li> <li>continuity protections;</li> <li>conflicts of interest and funding relationships.</li></ul> <p>No authority record, no compulsory action.</p> <h2>3.2 Functional separation</h2> <p>The following functions must remain distinguishable:</p> <ol><li>journalism and editorial judgment;</li> <li>scientific, historical, technical, and community research;</li> <li>standards development;</li> <li>platform assessment and audit;</li> <li>public regulation;</li> <li>crisis information coordination;</li> <li>prosecution or public enforcement;</li> <li>adjudication and remedy;</li> <li>media funding and grant administration;</li> <li>evaluation of the Protocol itself.</li></ol> <p>One institution may perform compatible administrative functions, but it may not classify a claim, trigger liability, prosecute the case, adjudicate it, receive the fine, and evaluate its own success.</p> <h2>3.3 Meta-Governance boundary</h2> <p>Meta-Governance may convene competent institutions, map interfaces, preserve disagreement, and support voluntary coordination. It may not determine truth, legal liability, media eligibility, content restrictions, tax rates, or emergency powers.</p> <h2>3.4 Advisory findings</h2> <p>Media reports, expert assessments, community testimony, fact-checks, audits, and state estimates may support inquiry. They do not create legal presumptions unless valid law expressly and constitutionally provides otherwise.</p> <hr> <h1>4. Claim, conduct, and harm taxonomy</h1> <h2>4.1 Claim types</h2> <p>A <strong>Claim, Conduct, and Harm Classification Record</strong> must distinguish at least:</p> <ul><li>verifiable factual assertion;</li> <li>probabilistic forecast or model output;</li> <li>scientific hypothesis or interpretation;</li> <li>historical claim or interpretation;</li> <li>personal testimony;</li> <li>opinion or value judgment;</li> <li>legal claim;</li> <li>religious, spiritual, contemplative, or metaphysical expression;</li> <li>satire, parody, fiction, art, or rhetorical exaggeration;</li> <li>quotation, translation, summary, or archival reproduction;</li> <li>synthetic media or impersonated communication;</li> <li>uncertain attribution;</li> <li>contested or unresolved claim.</li></ul> <h2>4.2 Conduct types</h2> <p>System conduct may include:</p> <ul><li>paid promotion and sponsorship;</li> <li>behavioural targeting;</li> <li>recommendation and ranking;</li> <li>trending and virality design;</li> <li>automated account operation;</li> <li>coordinated inauthentic behaviour;</li> <li>deceptive impersonation;</li> <li>synthetic-media generation;</li> <li>suppression, demotion, or removal;</li> <li>monetization and revenue sharing;</li> <li>data extraction and vulnerability profiling;</li> <li>notification, autoplay, streak, and engagement design;</li> <li>cross-platform coordination;</li> <li>government or corporate influence over editorial or platform decisions.</li></ul> <h2>4.3 Harm types</h2> <p>Possible harms must be described specifically, such as:</p> <ul><li>imminent and foreseeable physical harm;</li> <li>fraud or material deception;</li> <li>unlawful discrimination or denial of rights;</li> <li>targeted harassment or intimidation;</li> <li>privacy, data, or identity harm;</li> <li>deceptive electoral or governmental interference;</li> <li>obstruction of emergency communication;</li> <li>source exposure or journalist endangerment;</li> <li>destruction, alteration, or suppression of public records;</li> <li>extraction or publication of protected Indigenous or community knowledge;</li> <li>market, labour, or civic dependency created by platform design;</li> <li>unequal amplification or overblocking affecting protected groups;</li> <li>independently unlawful content or conduct.</li></ul> <h2>4.4 No truth-to-harm shortcut</h2> <p>A false statement is not automatically a legal harm. A true statement can also cause harm but may remain protected. Legal response depends on the applicable law, context, fault, causation, rights, necessity, proportionality, and available remedies.</p> <h2>4.5 Coordinated deception</h2> <p>“Coordinated deception” requires evidence of coordinated conduct, concealed identity or sponsorship, material misrepresentation, and a defined intended or foreseeable effect. Mere ideological similarity, rapid sharing, dissent, or unpopular interpretation is insufficient.</p> <hr> <h1>5. Evidence, uncertainty, and plural state estimates</h1> <h2>5.1 Observation Contract</h2> <p>A consequential assessment must state:</p> <ul><li>the question being examined;</li> <li>the observation period and population;</li> <li>data sources and missing populations;</li> <li>collection and measurement methods;</li> <li>known confounders;</li> <li>privacy, source, and protected-knowledge constraints;</li> <li>what the evidence cannot establish;</li> <li>who may access the underlying material;</li> <li>correction and deletion conditions.</li></ul> <h2>5.2 Public Claim and Uncertainty Record</h2> <p>For a high-consequence public claim, the publisher or assessing institution should distinguish:</p> <ul><li>observed facts;</li> <li>source testimony;</li> <li>inference;</li> <li>model output;</li> <li>interpretation;</li> <li>uncertainty;</li> <li>disputed evidence;</li> <li>conditions that would change the conclusion;</li> <li>correction history.</li></ul> <p>This record is a transparency practice, not a universal publication mandate for every speaker.</p> <h2>5.3 State Estimate Record</h2> <p>Where action depends on uncertain conditions, competent institutions should publish one or more state estimates identifying:</p> <ul><li>competing interpretations;</li> <li>confidence and uncertainty;</li> <li>distributional consequences of error;</li> <li>reversible options;</li> <li>excluded or protected evidence;</li> <li>decision authority;</li> <li>review date and change conditions.</li></ul> <h2>5.4 Observer and source independence</h2> <p>An <strong>Observer and Source Independence Map</strong> must disclose shared funders, ownership, datasets, models, experts, institutional affiliations, vendors, and communication channels. Numerically distinct institutions are not independent if they depend on the same source or infrastructure.</p> <h2>5.5 Burdens and standards of proof</h2> <p>This Protocol does not assign legal burdens of proof for technology, health, environment, history, or platform liability. Applicable law and Justice Systems govern those burdens. Advisory bodies may describe evidentiary uncertainty but may not reverse legal burdens by declaration.</p> <h2>5.6 Precaution under uncertainty</h2> <p>A Synoptic institution may recommend narrow, reversible protective steps where delay creates serious risk. Compulsory action requires valid authority, a defined harm, proportionality, continuity protection, review, and appeal.</p> <h2>5.7 Dissent and challenge</h2> <p>Dissent records must support:</p> <ul><li>named, pseudonymous, confidential, or institutional attribution as appropriate;</li> <li>anti-retaliation measures;</li> <li>correction and withdrawal;</li> <li>conditions for reconsideration;</li> <li>protected evidence and source confidentiality;</li> <li>separation between dissent and misconduct findings.</li></ul> <hr> <h1>6. Epistemic plurality and protected non-transfer</h1> <h2>6.1 Claim-specific methods</h2> <p>No fixed table assigns one epistemology exclusive authority over a whole domain. The relevant methods depend on the claim. A river-governance decision, for example, may require hydrology, law, Indigenous authority, local observation, ecological modelling, historical evidence, and value judgments that cannot be reduced to one method.</p> <h2>6.2 Equal dignity is not methodological interchangeability</h2> <p>Scientific, legal, Indigenous, community, journalistic, historical, artistic, and contemplative practices may all carry value without being interchangeable. A method’s relevance depends on the question, jurisdiction, source authority, and limits of the claim.</p> <h2>6.3 Indigenous and community knowledge</h2> <p>Indigenous or community knowledge is not a global epistemic resource available for institutional inclusion. Its custodians may require:</p> <ul><li>non-digitization;</li> <li>local-only use;</li> <li>non-publication;</li> <li>non-translation;</li> <li>non-training;</li> <li>non-commercial use;</li> <li>seasonal or role-based access;</li> <li>return, deletion, or repatriation;</li> <li>refusal without explanation.</li></ul> <h2>6.4 Protected non-transfer</h2> <p>A <strong>Protected Non-Transfer Record</strong> identifies information that must not move across a stated boundary. Transparency, red-teaming, research access, public funding, or archive preservation do not override that restriction without lawful authority from the relevant rights-holder or jurisdiction.</p> <h2>6.5 Unresolved plurality</h2> <p>The Protocol must preserve cases where communities, disciplines, or legal orders remain in legitimate disagreement. Coordination does not require one account to absorb the others.</p> <hr> <h1>7. Public-interest media ecosystem</h1> <h2>7.1 Purpose</h2> <p>Public-interest media institutions provide reporting, investigation, explanation, translation, local communication, archives, and public-service information where commercial markets undersupply them.</p> <h2>7.2 Plural institutional forms</h2> <p>Eligible forms may include:</p> <ul><li>public-service broadcasters with statutory independence;</li> <li>nonprofit investigative organizations;</li> <li>journalist and worker cooperatives;</li> <li>local and community media;</li> <li>Indigenous-created media institutions;</li> <li>university or library-based reporting initiatives;</li> <li>multilingual and disability-led media;</li> <li>emergency public-information services;</li> <li>independent fact-checking and verification organizations.</li></ul> <p>No form has privileged legal standing merely because it receives public support.</p> <h2>7.3 Public-Interest Media Charter</h2> <p>Each institution must publish a charter addressing:</p> <ul><li>editorial mission and legal status;</li> <li>editorial independence;</li> <li>governance and appointment methods;</li> <li>source protection;</li> <li>corrections and responses;</li> <li>conflicts of interest;</li> <li>funding disclosure;</li> <li>accessibility and language access;</li> <li>archive custody;</li> <li>staff and freelancer rights;</li> <li>investigation of the funder and governing institutions;</li> <li>succession, closure, and asset disposition.</li></ul> <h2>7.4 Editorial independence</h2> <p>Governments, Treaty institutions, fund administrators, platforms, donors, advertisers, political parties, and the GGF may not direct editorial conclusions. Funding conditions may address eligibility, accounting, accessibility, and public-service obligations but not viewpoint or desired trust outcomes.</p> <h2>7.5 No liability-trigger authority</h2> <p>A public-interest media institution may investigate, publish, correct, and submit evidence. Its flag, label, trustmark, or conclusion does not by itself establish platform liability, justify suppression, reverse a burden of proof, or create a market-access consequence.</p> <h2>7.6 Corrections and accountability</h2> <p>Institutions must provide visible and proportionate correction, retraction, response, and complaint routes. Correction systems must not become instruments for powerful actors to exhaust or intimidate journalists.</p> <h2>7.7 Right to criticize the system</h2> <p>Funded institutions retain the right to investigate and criticize the Synoptic Protocol, its funders, the Treaty, the GGF, public authorities, platforms, and other funded media without retaliation.</p> <hr> <h1>8. Independent media funding</h1> <h2>8.1 Funding-source separation</h2> <p>Media funding may arise from lawful public appropriations, jurisdiction-specific levies, endowments, membership, donations, philanthropy, cooperative revenue, subscriptions, or other lawful sources. The Synoptic Protocol does not create a tax.</p> <h2>8.2 Funding firewall</h2> <p>A <strong>Public-Interest Media Fund Custody Record</strong> must separate:</p> <ul><li>revenue collection;</li> <li>fund custody;</li> <li>grant eligibility;</li> <li>grant selection;</li> <li>editorial decisions;</li> <li>audit;</li> <li>complaint and appeal;</li> <li>evaluation.</li></ul> <h2>8.3 Grant allocation</h2> <p>Grant criteria may consider underserved populations, local news scarcity, linguistic access, investigative capacity, accessibility, source protection, and organizational resilience. They may not reward ideological alignment, desired belief change, increased trust in government, or reduced lawful dissent.</p> <h2>8.4 Fine-to-narrator prohibition</h2> <p>Fines from information-system cases must not automatically fund the institution that classified, investigated, or advocated the alleged violation. Any allocation requires separate lawful authority and conflict safeguards.</p> <h2>8.5 Funding diversity</h2> <p>Funds should avoid dependency on one government, platform, donor, or Treaty body. Small and local institutions require simplified access, predictable multi-year support, and protection from administrative burden.</p> <h2>8.6 Closure and continuity</h2> <p>Funding agreements must address staff claims, source protection, archives, ongoing investigations, unspent restricted funds, data return, and successor custody if an institution closes.</p> <hr> <h1>9. Media literacy and public education</h1> <h2>9.1 Educational purpose</h2> <p>Media literacy supports people in evaluating sources, understanding uncertainty, recognizing sponsorship and manipulation, protecting privacy, comparing interpretations, and participating in public discourse.</p> <h2>9.2 Curriculum authority</h2> <p>Curricula are adopted through the lawful education authority of the participating jurisdiction or institution. The Synoptic Protocol offers modules and review tools but does not mandate a global curriculum.</p> <h2>9.3 Core modules</h2> <p>Possible modules include:</p> <ul><li>source evaluation and provenance;</li> <li>logic, causation, probability, and uncertainty;</li> <li>statistical and visual literacy;</li> <li>scientific, historical, legal, and journalistic methods;</li> <li>advertising, targeting, and recommender systems;</li> <li>synthetic media and impersonation;</li> <li>privacy and cognitive self-defence;</li> <li>correction, dialogue, and belief revision;</li> <li>institutional incentives and fallibility;</li> <li>Indigenous and community knowledge boundaries;</li> <li>safe online participation and source protection.</li></ul> <h2>9.4 Prohibited curricular uses</h2> <p>Public curricula must not:</p> <ul><li>assign learners to developmental or worldview stages;</li> <li>teach obedience to an official source hierarchy;</li> <li>require political, religious, metaphysical, or GGF alignment;</li> <li>collect unnecessary belief or psychographic profiles;</li> <li>treat dissent as pathology;</li> <li>present public institutions as epistemically infallible.</li></ul> <h2>9.5 Plurality review</h2> <p>A <strong>Curriculum Authority and Plurality Review</strong> assesses source diversity, ideological loading, accessibility, local authority, age appropriateness, data practices, opt-out rules, teacher autonomy, and correction procedures.</p> <hr> <h1>10. Communication, explanation, and correction practices</h1> <h2>10.1 Multiple legitimate formats</h2> <p>Institutions may use direct fact-checking, investigative reporting, explanatory journalism, data visualization, dialogue, narrative, Q&A, community radio, testimony, debate, or other transparent methods. No single format is mandatory or prohibited by this Protocol.</p> <h2>10.2 Voluntary Sense-Making Toolkit</h2> <p>The former sense-making concept survives only as a voluntary toolkit. It may encourage:</p> <ul><li>respectful acknowledgment of the person’s stated concern;</li> <li>separation of evidence from identity or group status;</li> <li>accessible explanation of methods and uncertainty;</li> <li>direct correction where supported;</li> <li>links to primary or independent sources;</li> <li>invitation to inspect or challenge the reasoning.</li></ul> <p>It must not require invented emotional validation, therapeutic diagnosis, covert persuasion, or strategic identity manipulation.</p> <h2>10.3 Persuasion disclosure</h2> <p>Publicly funded campaigns and crisis communications must disclose:</p> <ul><li>institutional source;</li> <li>purpose;</li> <li>sponsorship;</li> <li>use of targeting or audience segmentation;</li> <li>use of automation or synthetic media;</li> <li>material uncertainty;</li> <li>correction and complaint channels.</li></ul> <h2>10.4 Audience adaptation</h2> <p>Communication may be adapted for language, literacy, disability, age, technical background, local context, and user-selected detail. Institutions must not infer hidden psychological or developmental categories to tailor political persuasion.</p> <h2>10.5 Correction standards</h2> <p>Corrections should be timely, linked to the original material, proportionate to reach, and clear about what changed. A correction does not require compelled ideological interpretation or ritual apology unless separately agreed or legally ordered.</p> <hr> <h1>11. Public deliberation and bridging dialogue</h1> <h2>11.1 Voluntary participation</h2> <p>Bridging dialogues, citizen assemblies, community sense-making groups, and deliberative platforms may support understanding and policy advice. Participation must be voluntary unless a lawful civic process provides otherwise.</p> <h2>11.2 Non-authorizing status</h2> <p>A dialogue or assembly does not create jurisdiction, determine truth, bind non-participants, validate a public narrative, or substitute for ratification, legislation, Indigenous consent, or adjudication.</p> <h2>11.3 Dialogue safeguards</h2> <p>A <strong>Dialogue or Assembly Charter</strong> must address:</p> <ul><li>purpose and sponsor;</li> <li>participant selection;</li> <li>facilitator authority;</li> <li>agenda setting;</li> <li>evidence and expert selection;</li> <li>accessibility and compensation;</li> <li>recording and privacy;</li> <li>conflict and safety protocols;</li> <li>minority and dissent reporting;</li> <li>non-retaliation;</li> <li>legal effect and limits.</li></ul> <h2>11.4 Facilitation neutrality</h2> <p>Facilitators may structure conversation and enforce conduct rules. They may not covertly steer participants toward a predetermined belief, diagnosis, or political outcome.</p> <h2>11.5 Community control</h2> <p>Local communication nodes may choose radio, print, oral, digital, or face-to-face methods. Participation in a global platform or shared dashboard is not required.</p> <hr> <h1>12. Recommender-system scope</h1> <h2>12.1 Covered systems</h2> <p>A <strong>Recommender-System Description Record</strong> identifies whether a system controls:</p> <ul><li>home feeds and timelines;</li> <li>search ranking;</li> <li>trending lists;</li> <li>notifications;</li> <li>autoplay and next-content selection;</li> <li>friend, group, channel, or account suggestions;</li> <li>advertising placement;</li> <li>sponsored or paid amplification;</li> <li>virality thresholds and resharing friction;</li> <li>moderation prioritization;</li> <li>monetization eligibility;</li> <li>cross-product recommendations.</li></ul> <h2>12.2 Scope threshold</h2> <p>Binding duties depend on valid law and may consider scale, market power, essential-service status, user vulnerability, targeting capacity, foreseeable harm, and cross-border impact. User count alone is not sufficient.</p> <h2>12.3 Direct and private communication</h2> <p>Private messaging and direct user choice require strong confidentiality. Applicable law may still govern spam, fraud, threats, malware, unlawful surveillance, or coordinated inauthentic operations.</p> <h2>12.4 System changes</h2> <p>Material changes to ranking objectives, targeting data, monetization, virality, operator control, or deployment context require updated documentation and, where law requires, reassessment.</p> <hr> <h1>13. Platform systemic-risk duties</h1> <h2>13.1 Authority condition</h2> <p>The duties in this section become compulsory only through valid law, regulation, contract, procurement, or platform commitment.</p> <h2>13.2 Risk assessment</h2> <p>Covered platforms may be required to assess:</p> <ul><li>amplification of independently unlawful content or conduct;</li> <li>deceptive impersonation and coordinated automation;</li> <li>discriminatory targeting or exclusion;</li> <li>harassment and violence pathways;</li> <li>manipulation of children or vulnerable users;</li> <li>covert political and commercial sponsorship;</li> <li>public-health and emergency communication risks;</li> <li>concentration and dependency;</li> <li>over-removal and unequal moderation;</li> <li>journalist, researcher, and source safety;</li> <li>effects on minority-language and low-resource communities.</li></ul> <h2>13.3 Mitigation duties</h2> <p>Lawful mitigations may include:</p> <ul><li>user controls and friction;</li> <li>sponsorship and bot disclosure;</li> <li>limits on sensitive targeting;</li> <li>authentication of official crisis sources;</li> <li>provenance tools;</li> <li>better complaint and appeal systems;</li> <li>researcher access;</li> <li>incident response;</li> <li>independent audit;</li> <li>changes to incentives, ranking, or monetization;</li> <li>narrow restrictions ordered by a competent authority.</li></ul> <h2>13.4 No institution-triggered liability</h2> <p>A finding by three or any number of media institutions does not establish liability. Reports and flags may trigger platform review, regulator inquiry, evidence preservation, or a complaint to a competent court.</p> <h2>13.5 Fault and causation</h2> <p>Any liability regime must define fault, notice, causation, foreseeability, defences, protected expression, safe harbours, evidence access, jurisdiction, appeal, and remedy. This framework does not supply those legal elements by itself.</p> <h2>13.6 Research access</h2> <p>Qualified independent researchers may receive privacy-preserving and security-bounded access under Aurora. Access must not expose personal data, confidential sources, protected knowledge, trade secrets beyond necessity, or system vulnerabilities.</p> <hr> <h1>14. Algorithmic choice and user agency</h1> <h2>14.1 Feed and ranking controls</h2> <p>Where applicable and technically feasible, users should be able to:</p> <ul><li>select chronological or following-only feeds;</li> <li>reduce or disable personalization;</li> <li>choose topic and source diversity controls;</li> <li>view why content or advertising was recommended;</li> <li>reset or edit recommendation profiles;</li> <li>disable selected notification and autoplay features;</li> <li>control sensitive advertising categories;</li> <li>export relevant preference and subscription data;</li> <li>access an equivalent non-profiled or low-data mode.</li></ul> <h2>14.2 No official verified feed</h2> <p>Platforms or publishers may offer editorial products with disclosed methods. No public authority may certify a feed as the authoritative version of reality or require citizens to use it.</p> <h2>14.3 Meaningful choice</h2> <p>A nominal setting is insufficient where the default is coercive, the alternative is degraded, the explanation is misleading, or refusal causes loss of essential communication or public services.</p> <h2>14.4 Children and dependent users</h2> <p>Systems used by children, students, workers, patients, benefit recipients, or people in institutional care require heightened safeguards against manipulative defaults and coerced consent.</p> <h2>14.5 Explanation and contest</h2> <p>A <strong>User Choice and Explanation Record</strong> documents available controls, defaults, material consequences, accessibility, profiling data, reset procedures, complaint routes, and restoration after error.</p> <hr> <h1>15. Independent audit and accreditation</h1> <h2>15.1 Functional independence</h2> <p>Standards developers, auditors, accreditation bodies, regulators, platforms, media institutions, funders, and courts must have disclosed and bounded roles.</p> <h2>15.2 Audit scope</h2> <p>An audit must identify:</p> <ul><li>question and legal authority;</li> <li>system boundary and version;</li> <li>data and sampling;</li> <li>access limitations;</li> <li>methods and uncertainty;</li> <li>security and source constraints;</li> <li>conflicts of interest;</li> <li>reproducibility conditions;</li> <li>affected-party participation;</li> <li>publication and protected annexes;</li> <li>correction and challenge routes.</li></ul> <h2>15.3 Accreditation</h2> <p>Accreditation evaluates auditor competence, independence, security, methods, and conflicts. Accreditation does not make every finding legally binding.</p> <h2>15.4 Layered transparency</h2> <p>Audit outputs may include:</p> <ul><li>a public summary;</li> <li>a regulator or court record;</li> <li>a protected technical annex;</li> <li>a confidential source or security annex.</li></ul> <p>Total public disclosure is neither necessary nor always safe.</p> <h2>15.5 Audit contestability</h2> <p>Platforms, workers, users, journalists, communities, and affected groups may challenge methods, exclusions, conflicts, or conclusions through the applicable process. Challenge does not automatically suspend urgent lawful protection.</p> <hr> <h1>16. Coordinated influence, bots, and synthetic impersonation</h1> <h2>16.1 Conduct focus</h2> <p>Governance targets deceptive conduct, not political viewpoint. Relevant conduct may include:</p> <ul><li>concealed government, corporate, or campaign sponsorship;</li> <li>coordinated fake identities;</li> <li>bot networks presented as organic public support;</li> <li>forged documents or impersonated officials;</li> <li>paid influence without disclosure;</li> <li>stolen or manipulated accounts;</li> <li>coordinated harassment;</li> <li>fraudulent engagement markets.</li></ul> <h2>16.2 Automation disclosure</h2> <p>Covered automated accounts and synthetic spokespersons should disclose their automated or synthetic nature where valid law or platform rules require it. Exceptions may protect benign technical services, security research, satire, privacy, or vulnerable speakers.</p> <h2>16.3 Attribution uncertainty</h2> <p>Institutions must distinguish observed coordination from inferred sponsorship and confirmed attribution. Premature state or group attribution can escalate conflict and endanger innocent people.</p> <h2>16.4 Political neutrality</h2> <p>The same conduct rules must apply to governments, parties, companies, civil society, Treaty institutions, and GGF-affiliated actors.</p> <h2>16.5 Evidence preservation</h2> <p>Evidence of coordinated influence must be preserved under Aurora and transferred through a Justice Referral and Evidence Custody Record where legal action is sought.</p> <hr> <h1>17. Deepfake and content-authenticity infrastructure</h1> <h2>17.1 Provenance tools</h2> <p>Interoperable provenance, watermarking, signing, and capture-authentication tools may help identify origin and modification. They are evidentiary aids, not proof of truth.</p> <h2>17.2 No-authentication presumption</h2> <p>Content lacking a watermark or signature is not presumed false or unlawful. Journalists, whistleblowers, artists, vulnerable communities, and people using low-resource tools may be unable or unwilling to authenticate content.</p> <h2>17.3 Protected expression</h2> <p>Satire, parody, anonymity, artistic transformation, reenactment, privacy protection, and investigative journalism require safeguards. Deceptive impersonation may be restricted where it creates a defined legal harm.</p> <h2>17.4 Official communications</h2> <p>Public authorities should authenticate high-consequence official communications through multiple accessible channels. Authentication systems must have offline and low-tech fallbacks.</p> <h2>17.5 Correction and incident response</h2> <p>Where synthetic impersonation is discovered, institutions should publish the evidence, uncertainty, authentic source, affected channels, and correction history without unnecessarily reproducing harmful content.</p> <hr> <h1>18. Content moderation and speech safeguards</h1> <h2>18.1 System governance affects expression</h2> <p>Ranking, demotion, removal, demonetization, account action, search exclusion, and virality limits affect expression even when they regulate platform systems rather than prohibit speech directly.</p> <h2>18.2 Required safeguards</h2> <p>Compulsory or platform-governed moderation should provide, as appropriate:</p> <ul><li>clear rules;</li> <li>notice and reasons;</li> <li>access to the relevant evidence or a lawful summary;</li> <li>human review for consequential cases;</li> <li>appeal;</li> <li>time limits;</li> <li>correction and restoration;</li> <li>transparency reporting;</li> <li>safeguards for journalism, research, archives, satire, and public-interest documentation;</li> <li>review of unequal and discriminatory impact.</li></ul> <h2>18.3 Independently unlawful material</h2> <p>Content already unlawful under valid law may be handled under that law. The Synoptic Protocol does not create new prohibited categories such as “reality erasure” or “epistemic disloyalty.”</p> <h2>18.4 Government requests</h2> <p>Platforms must disclose and challenge unlawful or overbroad government requests where legally possible. Emergency confidentiality must be time-bounded and independently reviewable.</p> <h2>18.5 Restoration after error</h2> <p>Where content or accounts were wrongly restricted, remedies may include reinstatement, reach restoration, correction of strikes, notice to affected users, data correction, compensation where law permits, and audit of the failure.</p> <hr> <h1>19. Interim restrictions and circuit breakers</h1> <h2>19.1 Intervention classes</h2> <p>The phrase “circuit breaker” must be replaced by the actual authority class:</p> <ol><li>user-selected control;</li> <li>voluntary operator measure;</li> <li>contractual or procurement condition;</li> <li>lawful regulator order;</li> <li>judicial injunction;</li> <li>valid emergency measure;</li> <li>public advisory;</li> <li>infrastructure continuity measure by a lawful operator;</li> <li>legislative moratorium.</li></ol> <h2>19.2 Interim Amplification Restriction Record</h2> <p>A compulsory interim restriction must identify:</p> <ul><li>legal authority and jurisdiction;</li> <li>defined harm and evidence;</li> <li>content, conduct, account, feature, or system affected;</li> <li>why less restrictive measures are inadequate;</li> <li>protected speech and continuity impacts;</li> <li>duration and maximum renewal;</li> <li>independent review;</li> <li>challenge route;</li> <li>restoration if the order was mistaken;</li> <li>public and protected reporting.</li></ul> <h2>19.3 No self-activation</h2> <p>Media flags, virality metrics, trust scores, social-conflict measures, council votes, or platform dashboards do not themselves create emergency authority.</p> <h2>19.4 No self-renewal</h2> <p>The body implementing a compulsory restriction cannot extend its own authority without the independent review required by the constituting law.</p> <h2>19.5 Narrowness</h2> <p>Where feasible, interventions should target deceptive conduct, monetization, targeting, automation, or virality mechanisms rather than suppress the underlying lawful expression.</p> <h2>19.6 Continuity</h2> <p>Restrictions must protect emergency communication, journalism, archives, disability access, minority-language communication, workers, small organizations, and people dependent on the platform for essential contact.</p> <hr> <h1>20. Crisis public-information coordination</h1> <h2>20.1 Purpose</h2> <p>Crisis Information Coordination Cells may help competent authorities and independent media authenticate sources, translate instructions, explain uncertainty, correct false official information, preserve communication channels, and support low-bandwidth access.</p> <h2>20.2 Authority and activation</h2> <p>Each cell requires a <strong>Crisis Information Activation and Authority Record</strong> identifying:</p> <ul><li>crisis class;</li> <li>host and legal authority;</li> <li>participating institutions;</li> <li>scope and prohibited functions;</li> <li>information sources;</li> <li>privacy and source rules;</li> <li>expiry;</li> <li>independent review;</li> <li>public correction route.</li></ul> <h2>20.3 Permitted functions</h2> <p>A cell may:</p> <ul><li>maintain a verified directory of official and independent sources;</li> <li>authenticate documents and communications;</li> <li>translate and explain public instructions;</li> <li>publish uncertainty and competing state estimates;</li> <li>coordinate corrections;</li> <li>preserve access through radio, print, mesh, satellite, and community networks;</li> <li>identify impersonation and manipulated media;</li> <li>support journalists and local communicators;</li> <li>record decisions and errors.</li></ul> <h2>20.4 Prohibited functions</h2> <p>A cell may not:</p> <ul><li>create political counter-narratives;</li> <li>target ideological groups for belief change;</li> <li>suppress criticism because it reduces confidence;</li> <li>classify opposition reporting as an emergency merely because it conflicts with official messaging;</li> <li>conduct covert influence operations;</li> <li>direct media conclusions;</li> <li>extend its own emergency powers;</li> <li>conceal material uncertainty.</li></ul> <h2>20.5 Source plurality</h2> <p>Crisis communication should distinguish official instruction, independent reporting, expert assessment, community observation, and unresolved claims. Official status does not guarantee factual accuracy.</p> <h2>20.6 After-action review</h2> <p>Every activation requires review of errors, overblocking, delayed corrections, excluded groups, security incidents, political pressure, accessibility, and restoration.</p> <hr> <h1>21. Journalism, research, whistleblowers, and archives</h1> <h2>21.1 Editorial and research independence</h2> <p>Journalists and researchers must remain free to investigate public authorities, platforms, funders, Treaty institutions, public-interest media, and Synoptic mechanisms.</p> <h2>21.2 Source confidentiality</h2> <p>Confidential-source identity and communications may be disclosed only under valid law, strict necessity, proportionality, and independent review. Audit or research access does not automatically override source protection.</p> <h2>21.3 Whistleblowers</h2> <p>Whistleblowers require secure reporting, anti-retaliation, legal advice, privacy, employment protection, and referral to competent authorities. The Protocol does not promise immunity from all lawful obligations.</p> <h2>21.4 Archives</h2> <p>Archive policy must balance:</p> <ul><li>historical preservation;</li> <li>public records;</li> <li>correction and annotation;</li> <li>privacy and data rights;</li> <li>expungement and sealed records;</li> <li>source safety;</li> <li>Indigenous and community authority;</li> <li>security and conflict sensitivity;</li> <li>succession and format migration.</li></ul> <h2>21.5 No archive absolutism</h2> <p>Preservation does not automatically override deletion, non-publication, repatriation, protected non-transfer, or source-protection obligations.</p> <h2>21.6 Epistemic asylum and relocation referrals</h2> <p>Journalists, researchers, librarians, and truth-tellers facing persecution may be referred to lawful asylum, visa, relocation, fellowship, and protection programmes. Synoptic institutions do not themselves grant asylum.</p> <hr> <h1>22. Authoritarian-context resilience</h1> <h2>22.1 Protected objectives</h2> <p>Legitimate objectives include:</p> <ul><li>preserving independent archives;</li> <li>supporting secure journalism;</li> <li>maintaining diaspora and community media;</li> <li>providing digital and physical safety training;</li> <li>supporting legal defence and relocation;</li> <li>preserving minority languages and cultural memory;</li> <li>enabling secure communication under lawful human-rights work.</li></ul> <h2>22.2 Prohibition on covert GGF operations</h2> <p>The Protocol does not authorize deniable cells, hidden GGF affiliation, covert political organization, clandestine influence campaigns, or unauthorized operations in another jurisdiction.</p> <h2>22.3 Partner autonomy</h2> <p>Support should be delivered through independent organizations with their own governance, risk assessment, local knowledge, and duty of care. Funders may not expose partners by requiring public branding or centralized reporting of sensitive networks.</p> <h2>22.4 Safety and legality</h2> <p>An <strong>Authoritarian-Context Partner Safety Record</strong> identifies:</p> <ul><li>partner consent and governance;</li> <li>legal and security risks;</li> <li>data minimization;</li> <li>disclosure limits;</li> <li>funding and procurement;</li> <li>participant support;</li> <li>incident response;</li> <li>exit and destruction of sensitive records;</li> <li>independent review.</li></ul> <h2>22.5 Non-abandonment</h2> <p>A funder or international partner that encourages risky activity must plan for legal aid, emergency relocation, livelihood continuity, family protection, and programme wind-down.</p> <hr> <h1>23. Indigenous, community, and cultural knowledge interfaces</h1> <h2>23.1 Recognition, not creation</h2> <p>The Protocol recognizes Indigenous peoples’ own authorities, media, archives, laws, knowledge protocols, and consent processes. It does not create a universal Indigenous council or representation quota.</p> <h2>23.2 Affected-authority principle</h2> <p>Where reporting, research, platform design, archives, AI systems, or public communication affect Indigenous territory, identity, law, sacred relations, language, or knowledge, the relevant people’s authority and applicable interface must be identified.</p> <h2>23.3 Indigenous and Community Knowledge Interface Record</h2> <p>The record addresses:</p> <ul><li>authority and custodianship;</li> <li>purpose and scope;</li> <li>consent and refusal;</li> <li>publication and translation;</li> <li>attribution;</li> <li>data and archive custody;</li> <li>access limitations;</li> <li>commercial use;</li> <li>AI training and synthetic reproduction;</li> <li>correction, return, deletion, or repatriation;</li> <li>unresolved jurisdiction.</li></ul> <h2>23.4 Non-engagement</h2> <p>A people or community may decline participation without becoming an empty seat, missing perspective, failed diversity target, or obstacle to legitimacy.</p> <h2>23.5 Community testimony</h2> <p>Community testimony may be essential evidence. It is not automatically public, transferable, representative of all members, or available for universal reuse.</p> <hr> <h1>24. Data, privacy, identity, and audience research</h1> <h2>24.1 Aurora alignment</h2> <p>Audience analytics, recommendation profiles, ad targeting, user research, survey data, source records, audit data, and crisis communication records follow Aurora Accord.</p> <h2>24.2 No territorial data ownership presumption</h2> <p>A BAZ, state, platform, media institution, or community does not own all data generated within its territory or systems. Rights and duties may overlap among persons, relationships, communities, public authorities, custodians, and Indigenous peoples.</p> <h2>24.3 Psychographic restraint</h2> <p>Public institutions and funded media must not collect or infer political vulnerability, developmental stage, psychological state, religious identity, intelligence, sensitivity, or worldview unless strictly necessary, lawfully authorized, proportionate, and protected.</p> <h2>24.4 Audience research</h2> <p>Research must distinguish service improvement, accessibility testing, public-interest research, editorial analytics, political persuasion, and advertising. Hidden persuasion research is prohibited for public institutions.</p> <h2>24.5 Data minimization</h2> <p>Institutions must collect only what is necessary, set retention periods, support correction and deletion, separate identifiers from content, and protect sources and vulnerable communities.</p> <h2>24.6 Consent and dependency</h2> <p>Consent is not freely given when public services, education, employment, safety, healthcare, or essential communication depend on agreeing to invasive research or personalization.</p> <hr> <h1>25. Justice, remedies, and enforcement</h1> <h2>25.1 Justice Systems interface</h2> <p>Binding complaints, jurisdiction, standing, evidence, interim orders, discovery, confidentiality, hearings, appeals, remedies, and enforcement follow Justice Systems and the valid law creating the cause of action.</p> <h2>25.2 No Synoptic tribunal creation</h2> <p>This Protocol does not create an epistemic division of a tribunal or confer jurisdiction over disinformation, historical interpretation, platform design, or media practice.</p> <h2>25.3 No policy-body appeal</h2> <p>Standing, evidentiary, liability, and remedy decisions are appealed through the competent justice system, not to a media, standards, or epistemic policy body.</p> <h2>25.4 No mandatory mediation</h2> <p>Mediation may be offered but must not delay urgent protection, limitation periods, source safety, public-interest reporting, or authoritative adjudication. Victims and respondents may decline where mediation is unsafe or inappropriate.</p> <h2>25.5 Remedy hierarchy</h2> <p>Where law permits, remedies should be tailored in this approximate order:</p> <ol><li>explanation, disclosure, or data access;</li> <li>correction, annotation, or right of response;</li> <li>user controls, friction, or sponsorship disclosure;</li> <li>evidence preservation and independent audit;</li> <li>narrow targeting, monetization, or amplification restrictions;</li> <li>compensation or restitution;</li> <li>time-limited feature or service restrictions;</li> <li>structural or market remedies under valid law.</li></ol> <p>The least restrictive effective remedy is preferred, subject to seriousness, recurrence, fault, rights, and continuity.</p> <h2>25.6 Protected continuity</h2> <p>Remedies must consider journalism, archives, emergency communication, user data portability, workers, small businesses, disability access, minority-language communities, public records, and innocent users.</p> <h2>25.7 Restoration after wrongful intervention</h2> <p>A <strong>Remedy, Appeal, and Restoration Record</strong> documents reversal, reinstatement, correction, compensation, data repair, notification, institutional learning, and prevention of recurrence.</p> <hr> <h1>26. Funding, fiscal boundaries, and anti-capture</h1> <h2>26.1 Fiscal authority</h2> <p>Any levy on digital advertising, engagement-driven revenue, data extraction, or platform profit must be enacted by a competent jurisdiction or separately ratified fiscal instrument. The Synoptic Protocol cannot impose or adjust a tax.</p> <h2>26.2 Attention-extraction levies</h2> <p>A jurisdiction may consider an attention-extraction levy. Its law must define the tax base, rate, threshold, attribution, collection, appeals, anti-avoidance, international coordination, and allocation. Epistemic-health metrics do not automatically determine the rate.</p> <h2>26.3 Editorial non-control</h2> <p>Public funding cannot condition grants on favourable coverage, reduced criticism, trust in institutions, adoption of an official narrative, or achievement of belief-change targets.</p> <h2>26.4 Platform funding conflicts</h2> <p>Platform donations, in-kind infrastructure, cloud credits, advertising partnerships, or data access must be disclosed and may not purchase editorial influence, audit leniency, regulatory access, or preferential standards.</p> <h2>26.5 Administrative limits</h2> <p>Funding bodies may inspect finances and grant compliance. They may not inspect confidential sources, unpublished investigations, editorial deliberations, or protected knowledge except under valid and narrowly tailored law.</p> <h2>26.6 Procurement and vendor dependence</h2> <p>Media and crisis infrastructure should avoid lock-in to one platform, cloud, identity system, AI provider, or communications vendor. Contracts must support portability, security, exit, continuity, and archive transfer.</p> <hr> <h1>27. Metrics, evaluation, and anti-Goodhart rules</h1> <h2>27.1 Conditions, not one epistemic-health score</h2> <p>Evaluation should publish separate conditions rather than a composite score that purports to measure shared reality.</p> <h2>27.2 Appropriate dimensions</h2> <p>Possible dimensions include:</p> <ul><li>access to local and minority-language news;</li> <li>media ownership concentration;</li> <li>editorial independence;</li> <li>funding diversity;</li> <li>correction speed and visibility;</li> <li>source and journalist safety;</li> <li>public-information accessibility;</li> <li>user control over recommendation and targeting;</li> <li>sponsorship and automation disclosure;</li> <li>audit independence;</li> <li>complaint and appeal accessibility;</li> <li>overblocking and unequal impact;</li> <li>research access;</li> <li>archive resilience;</li> <li>crisis correction performance;</li> <li>excluded and missing populations;</li> <li>unresolved disputes and uncertainty.</li></ul> <h2>27.3 Prohibited targets</h2> <p>Evaluation must not require:</p> <ul><li>increased trust in government, the GGF, PEIs, or any named institution;</li> <li>reduced ideological disagreement;</li> <li>adoption of designated beliefs;</li> <li>reduced reporting of uncomfortable facts;</li> <li>social harmony as evidence of accuracy;</li> <li>a required number of false-content findings;</li> <li>a required reduction in sharing based solely on institutional flags.</li></ul> <h2>27.4 Interpretation safeguards</h2> <p>A fall in trust may reflect accurate reporting. Increased conflict may reflect previously silenced harms becoming visible. Low correction rates may reflect accuracy or inaccessible complaint systems. Every indicator requires plural interpretation.</p> <h2>27.5 Independent evaluation</h2> <p>Evaluators must disclose methods, funders, data, exclusions, conflicts, and change conditions. Programmes may conclude that an intervention should not scale.</p> <hr> <h1>28. Implementation, pilots, and Genesis alignment</h1> <h2>28.1 Pre-constitutional and voluntary pilots</h2> <p>Before binding adoption, Synoptic pilots may test:</p> <ul><li>media-literacy modules;</li> <li>public-interest media charters and funding firewalls;</li> <li>correction and response formats;</li> <li>dialogue methods;</li> <li>user-controlled feeds;</li> <li>audit methods;</li> <li>provenance tools;</li> <li>crisis communication and low-bandwidth continuity;</li> <li>archive and source-protection systems.</li></ul> <h2>28.2 Pilot Constitutional Contract</h2> <p>Every pilot must specify:</p> <ul><li>lawful host authority;</li> <li>voluntary participation and refusal;</li> <li>rights and non-retaliation;</li> <li>data and source protection;</li> <li>funding and conflicts;</li> <li>evaluation questions;</li> <li>publication control;</li> <li>complaint route;</li> <li>exit and wind-down;</li> <li>no conversion of pilot success into legal authority.</li></ul> <h2>28.3 No compulsory pilot powers</h2> <p>A pilot may not impose taxes, binding platform duties, legal liability, compulsory content restrictions, market exclusions, or emergency powers without separate valid law.</p> <h2>28.4 Independent evaluation</h2> <p>Pilots must permit negative findings, non-transferability, minority reports, community-controlled publication, and the conclusion that scaling should stop.</p> <h2>28.5 Lawful adoption</h2> <p>Binding platform regulation, tax, public-media charter, emergency authority, or judicial remedy begins only after valid adoption under Treaty, domestic, Indigenous, compact, or other competent law.</p> <h2>28.6 First seating and founder separation</h2> <p>Any new public institution follows Genesis: lawful constituting authority, transparent first seating, asset and data custody, conflict disclosure, founder handoff, and no automatic successor centre.</p> <hr> <h1>29. Exit, dissolution, archives, and successor custody</h1> <h2>29.1 Exit</h2> <p>Participants, media institutions, platforms, communities, funders, and pilot hosts may exit according to applicable law and agreement. Exit does not erase lawfully incurred duties, evidence-preservation requirements, compensation, source protection, or worker claims.</p> <h2>29.2 No retaliation</h2> <p>Exit from a voluntary Synoptic programme must not cause loss of unrelated public rights, AUBI, essential services, justice access, or lawful market participation.</p> <h2>29.3 Institutional closure</h2> <p>Closure plans must address:</p> <ul><li>staff and contractor obligations;</li> <li>ongoing grants and investigations;</li> <li>confidential sources;</li> <li>personal and protected data;</li> <li>archive custody and access;</li> <li>domains, repositories, trademarks, and channels;</li> <li>equipment and restricted funds;</li> <li>complaints and pending cases;</li> <li>public notice and final audit.</li></ul> <h2>29.4 Successor custody</h2> <p>Archives, data, grants, and public communication channels may transfer only through lawful authority, purpose limitation, security review, source protection, and protected non-transfer.</p> <h2>29.5 Dissolution without successor</h2> <p>A programme or institution may dissolve without creating a replacement. Failure to continue is not automatically an epistemic emergency.</p> <hr> <h1>30. Amendment, review, and constitutional readiness gates</h1> <h2>30.1 Operational amendment</h2> <p>Before binding adoption, voluntary operational procedures may be amended under their charter, with transparent reasons, affected-party participation, and version history.</p> <h2>30.2 Binding-law amendment</h2> <p>After adoption, binding duties, taxes, jurisdiction, emergency powers, sanctions, and institutional mandates follow the amendment process of the constituting legal instrument.</p> <h2>30.3 Periodic review</h2> <p>At least every five years, participating institutions should review:</p> <ul><li>authority and scope;</li> <li>editorial and research independence;</li> <li>platform and government capture;</li> <li>overblocking and under-enforcement;</li> <li>source and archive safety;</li> <li>data practices;</li> <li>crisis powers;</li> <li>funding concentration;</li> <li>institutional necessity;</li> <li>possible narrowing, federation, transfer, or dissolution.</li></ul> <h2>30.4 Constitutional readiness gates</h2> <p>The Protocol is not ready for compulsory implementation unless it can pass all of the following:</p> <ol><li>no official reality;</li> <li>no media-institution flag that automatically creates liability;</li> <li>no claim that system regulation bypasses speech and press rights;</li> <li>no global epistemic sovereign;</li> <li>no developmental, sanity, intelligence, or worldview audience classification;</li> <li>no covert persuasion by public institutions;</li> <li>no mandatory narrative replacement;</li> <li>no self-activating emergency;</li> <li>no self-renewing restriction;</li> <li>no compulsory suppression without lawful basis and challenge;</li> <li>no official verified feed;</li> <li>no universal Indigenous proxy;</li> <li>no total public legibility of dissent;</li> <li>no territorial ownership of all local data;</li> <li>no mandatory mediation;</li> <li>no policy-body judicial appeal;</li> <li>no tax rate set by epistemic metrics;</li> <li>no automatic fine-to-narrator funding loop;</li> <li>no trust, harmony, or belief-conformity mandate;</li> <li>no covert GGF cells or deniable operations;</li> <li>no archive absolutism;</li> <li>failure can stop scaling;</li> <li>funded institutions remain free to criticize the framework and its funders;</li> <li>unresolved truth remains institutionally possible.</li></ol> <h2>30.5 Final legitimacy test</h2> <blockquote><p><strong>Could publicly funded media expose the GGF, a minority history contradict official consensus, a platform successfully challenge a false flag, an Indigenous people refuse disclosure, public trust decline after accurate reporting, and a crisis remain epistemically unresolved—without the system selecting an official reality, punishing lawful dissent, or activating covert persuasion?</strong></p></blockquote> <p>If the answer is no, the architecture is not ready.</p> <hr> <h1>Operational appendices and records</h1> <p>The records below are modular. A participating institution uses only those relevant to its lawful function. A record documents authority and reasoning; it does not create authority.</p> <h2>Appendix A — Epistemic Action Authority Record</h2> <p>Record the actor, constituting instrument, action, jurisdiction, affected rights, evidence, duration, review, appeal, continuity protections, and conflicts.</p> <h2>Appendix B — Claim, Conduct, and Harm Classification Record</h2> <p>Separate claim type, system conduct, alleged harm, legal basis, uncertainty, protected expression, and unresolved classification.</p> <h2>Appendix C — Observation Contract</h2> <p>Specify the question, population, data, methods, missing observations, confounders, prohibited uses, access, retention, and correction.</p> <h2>Appendix D — Public Claim and Uncertainty Record</h2> <p>Distinguish observation, testimony, inference, model, interpretation, confidence, disputed evidence, change conditions, and correction history.</p> <h2>Appendix E — State Estimate Record</h2> <p>Document competing state estimates, uncertainty, error costs, reversible options, decision authority, review date, and protected evidence.</p> <h2>Appendix F — Observer and Source Independence Map</h2> <p>Map ownership, funders, datasets, experts, models, vendors, affiliations, shared infrastructure, and possible correlated error.</p> <h2>Appendix G — Dissent, Attribution, and Protection Record</h2> <p>Record dissent with chosen attribution level, evidence, reconsideration conditions, anti-retaliation, source protection, correction, and withdrawal.</p> <h2>Appendix H — Indigenous and Community Knowledge Interface Record</h2> <p>Identify authority, custodianship, consent, refusal, access, publication, translation, attribution, commercial use, AI use, return, deletion, and unresolved jurisdiction.</p> <h2>Appendix I — Protected Non-Transfer Record</h2> <p>State the protected information, custodian, prohibited transfers and uses, duration, lawful exceptions, review, and return or deletion requirements.</p> <h2>Appendix J — Public-Interest Media Charter</h2> <p>Specify legal form, mission, editorial independence, governance, source protection, corrections, funding disclosure, accessibility, labour rights, archives, and closure.</p> <h2>Appendix K — Editorial Independence and Funding Firewall Record</h2> <p>Separate collection, custody, grants, editorial decisions, audit, evaluation, complaints, and conflicts; record prohibited funder influence.</p> <h2>Appendix L — Correction, Retraction, and Response Record</h2> <p>Document the original publication, complaint, evidence, decision, correction or refusal, reach, notification, appeal, and archive treatment.</p> <h2>Appendix M — Journalist and Source Protection Record</h2> <p>Record source sensitivity, access controls, legal risks, disclosure standard, security, retaliation protection, emergency contact, and closure handling.</p> <h2>Appendix N — Curriculum Authority and Plurality Review</h2> <p>Record adopting authority, learning goals, sources, ideological and cultural risks, accessibility, learner data, teacher autonomy, correction, and opt-out.</p> <h2>Appendix O — Communication Method and Persuasion Disclosure</h2> <p>Identify source, purpose, audience, adaptation variables, sponsorship, automation, targeting, uncertainty, prohibited psychographics, and complaint route.</p> <h2>Appendix P — Audience Data and Segmentation Record</h2> <p>Document audience data, legal basis, necessity, categories, profiling inferences, targeting, retention, access, opt-out, and prohibited uses.</p> <h2>Appendix Q — Dialogue or Assembly Charter</h2> <p>Specify sponsor, purpose, selection, facilitator role, evidence process, privacy, accessibility, compensation, minority reporting, safety, and legal effect.</p> <h2>Appendix R — Recommender-System Description Record</h2> <p>Describe ranking objectives, data, features, defaults, sponsorship, automation, user controls, moderation interfaces, versions, and accountable operator.</p> <h2>Appendix S — Platform Systemic-Risk Assessment</h2> <p>Record covered use, legal authority, risks, evidence, affected groups, mitigation options, rights, residual risk, review, and public/protected outputs.</p> <h2>Appendix T — Algorithmic Impact State Estimate</h2> <p>Publish competing interpretations of system effects, methods, uncertainty, distributional impacts, missing groups, and change conditions.</p> <h2>Appendix U — Independent Audit Scope and Conflict Record</h2> <p>Define authority, system boundary, version, access, methods, limitations, funders, conflicts, affected-party participation, publication, and challenge.</p> <h2>Appendix V — User Choice and Explanation Record</h2> <p>Document feed modes, personalization controls, defaults, consequences, profiling data, explanations, accessibility, reset, complaint, and restoration.</p> <h2>Appendix W — Sponsorship, Automation, and Provenance Disclosure Record</h2> <p>Record payer, beneficiary, automated actors, synthetic media, provenance method, targeting, distribution channels, and disclosure exceptions.</p> <h2>Appendix X — Coordinated Influence Operation Assessment</h2> <p>Separate observed coordination, identity evidence, sponsorship, automation, intent, attribution confidence, protected activity, and legal referral.</p> <h2>Appendix Y — Interim Amplification Restriction Record</h2> <p>State authority, harm, evidence, system element affected, narrowness, rights, continuity, duration, independent review, challenge, publication, and restoration.</p> <h2>Appendix Z — Crisis Information Activation and Authority Record</h2> <p>Identify crisis, host authority, participating institutions, permitted and prohibited functions, sources, expiry, review, data rules, and correction.</p> <h2>Appendix AA — Crisis Source Authentication and Correction Log</h2> <p>Track source claims, authentication methods, uncertainty, public communication, corrections, timestamps, affected channels, and unresolved attribution.</p> <h2>Appendix AB — Overblocking, Under-Enforcement, and Unequal-Impact Review</h2> <p>Measure false positives, false negatives, restoration, group impacts, language and disability effects, appeals, sampling limits, and corrective action.</p> <h2>Appendix AC — Justice Referral and Evidence Custody Record</h2> <p>Record complainant, legal basis, jurisdiction, standing, evidence chain, protected material, access, transfer, preservation, and receiving authority.</p> <h2>Appendix AD — Remedy, Appeal, and Restoration Record</h2> <p>Document order or agreement, affected parties, continuity, implementation, appeal, reversal, reinstatement, compensation, correction, and learning.</p> <h2>Appendix AE — Public-Interest Media Fund Custody Record</h2> <p>Record revenue authority, custodians, allocation rules, conflicts, grant process, editorial firewall, audit, appeal, reserves, and dissolution.</p> <h2>Appendix AF — Archive Custody, Access, and Succession Record</h2> <p>Identify archive scope, owners and custodians, source restrictions, privacy, correction, sealed records, protected knowledge, formats, succession, and deletion.</p> <h2>Appendix AG — Authoritarian-Context Partner Safety Record</h2> <p>Document partner governance, consent, risk, funding, data minimization, disclosure, security, legal support, relocation, family support, exit, and record destruction.</p> <h2>Appendix AH — Pilot Rights, Data, and Wind-Down Contract</h2> <p>Specify host authority, scope, participation, rights, non-retaliation, data, sources, funding, evaluation, publication, complaints, exit, assets, and non-conversion to authority.</p> <h2>Appendix AI — Framework Exit and Dissolution Record</h2> <p>Record terminating authority, notice, staff and participant rights, grants, archives, sources, data, domains, contracts, claims, successor custody, and final audit.</p> <hr> <h1>Closing statement</h1> <p>The Synoptic Protocol begins from a difficult reality: public knowledge is produced within systems of power, incentives, identity, language, technology, memory, and unequal access. Those systems can be made more transparent, plural, accountable, accessible, and resistant to manipulation.</p> <p>But the institution that protects inquiry must remain open to inquiry about itself. The media institution that receives public funds must remain free to expose its funder. The platform regulator must remain distinct from the narrator. The crisis communicator must report uncertainty rather than replace it with confidence. The archive must preserve without claiming everything may be possessed. The public must retain the right to disagree, reinterpret, investigate, refuse, and remain uncertain.</p> <blockquote><p><strong>Synoptic protects the conditions of shared inquiry. It does not make shared inquiry safe by ending the possibility of disagreement.</strong></p></blockquote>",1);function f(i){var e=r();n(1094),o(i,e)}export{f as default,a as metadata};
